import itertools
import numpy as np

# Define the function to check: LHS >= U * RHS
# U = 9/2 = 4.5
U = 4.5

def check_inequality(x, y, z):
    lhs = (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1)
    rhs = U * (x*y + y*z + z*x)
    return lhs >= rhs

# Test points covering various ratios and magnitudes
# We test a grid of points in the range [0.1, 3]
test_values = np.linspace(0.1, 3, 15)
counterexample_found = False

for x in test_values:
    for y in test_values:
        for z in test_values:
            if not check_inequality(x, y, z):
                print(f"Counterexample found: x={x}, y={y}, z={z}")
                counterexample_found = True
                break
        if counterexample_found:
            break
    if counterexample_found:
        break

if not counterexample_found:
    print("No counterexample found in the sampled region [0.1, 3].")

